import React,{useState,useEffect,useRef,useId} from 'react';
import {createRoot} from 'react-dom/client';
import {LayoutGrid,Palette,CalendarClock,Radio,Plug,Settings,Search,Plus,Upload,Download,ArrowUpRight,ArrowRight,Check,X,Copy,ImagePlus,Trash2,Edit3,Package,ChevronDown,CheckCircle2,AlertCircle,FileSpreadsheet,FolderOpen,ExternalLink,Clock,Layers,FileText,Archive,Menu,ShoppingBag,Store,Monitor,Smartphone,Image as ImageIcon,Send,RefreshCw,Bookmark,ChevronLeft,HelpCircle} from 'lucide-react';
import {markets,money,cents,discount,messageFor,defaultBody,renderCreative,slug,shrinkImage} from './domain.js';
import './styles.css';
import {Connections,SendForm} from './Connectors.jsx';
import {BulkScheduleForm} from './Workflow.jsx';
import {Coupons} from './Coupons.jsx';
import {ShopeeOffers} from './Shopee.jsx';

const blankProduct={title:'',marketplace:'shein',price:0,originalPrice:0,coupon:'',affiliateUrl:'',image:'',category:'',description:'',tags:[],status:'draft'};
const viewLabels={catalog:'Catálogo',shopee:'Ofertas Shopee',studio:'Estúdio criativo',queue:'Fila de publicação',channels:'Canais',templates:'Mensagens',coupons:'Cupons',integrations:'Integrações',settings:'Preferências'};
const statusLabel={draft:'Rascunho',ready:'Pronto',archived:'Arquivado',scheduled:'Agendado',done:'Publicado',cancelled:'Cancelado',sending:'Enviando',failed:'Falhou',unknown:'Conferir destino'};
const dateTime=d=>new Intl.DateTimeFormat('pt-BR',{dateStyle:'short',timeStyle:'short'}).format(new Date(d));
async function api(path,options={}){const headers={'X-Vitraya-Client':'1',...options.headers};if(options.body&&!(options.body instanceof FormData))headers['Content-Type']='application/json';const response=await fetch('/api'+path,{...options,headers,body:options.body instanceof FormData?options.body:options.body?JSON.stringify(options.body):undefined});const result=await response.json();if(!response.ok)throw new Error(result.error||'Não foi possível concluir a operação.');return result;}
function download(blob,name){const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
const Market=({id})=><span className={'market market-'+id}>{markets[id]||id}</span>;
function App(){
 const [state,setState]=useState(null),[view,setView]=useState('catalog'),[loadError,setLoadError]=useState(''),[busy,setBusy]=useState(false),[toast,setToast]=useState(null),[modal,setModal]=useState(null),[selected,setSelected]=useState([]),[studioId,setStudioId]=useState(''),[menu,setMenu]=useState(false);
 const operationRef=useRef(false);
 const notify=(text,error=false)=>setToast({text,error});
 async function refresh(){try{setState(await api('/state'));setLoadError('');}catch(e){setLoadError(e.message);}}
 useEffect(()=>{refresh();const timer=setInterval(refresh,30000);return()=>clearInterval(timer);},[]);
 useEffect(()=>{if(toast){const t=setTimeout(()=>setToast(null),5500);return()=>clearTimeout(t);}},[toast]);
 async function run(action,success){if(operationRef.current)throw new Error('Aguarde a operação em andamento.');operationRef.current=true;setBusy(true);try{const result=await action();await refresh();if(success)notify(success);return result;}catch(e){notify(e.message,true);throw e;}finally{operationRef.current=false;setBusy(false);}}
 function navigate(next){setView(next);setMenu(false);}
 function studio(product){setStudioId(product.id);navigate('studio');}
 if(!state)return <div className="loading-screen"><div className="brand-mark">v<span>●</span></div><h1>Vitraya Studio</h1><p>{loadError||'Abrindo sua mesa de trabalho…'}</p>{loadError&&<button className="button primary" onClick={refresh}><RefreshCw size={16}/>Tentar novamente</button>}</div>;
 const context={state,refresh,run,notify,busy,setModal,studio,selected,setSelected,api};
 const scheduled=state.campaigns.filter(c=>['scheduled','ready','sending','failed','unknown'].includes(c.status)).length;
 return <div className="app-shell">
  <a href="#main" className="skip-link">Pular para o conteúdo</a>
  <aside className={'sidebar '+(menu?'is-open':'')}>
   <button className="brand" onClick={()=>navigate('catalog')} aria-label="Vitraya Studio, catálogo"><span className="brand-mark">v<span>●</span></span><span>vitraya<small>STUDIO</small></span></button>
   <div className="workspace-tag"><span className="workspace-avatar">V</span><span>Meu espaço<small>Operação local</small></span><ChevronDown size={14}/></div>
   <div className="nav-label">CRIAR E PUBLICAR</div>
   <nav aria-label="Navegação principal">{[[LayoutGrid,'catalog'],[Store,'shopee'],[Palette,'studio'],[CalendarClock,'queue'],[Radio,'channels'],[FileText,'templates'],[ShoppingBag,'coupons']].map(([Icon,key])=><button key={key} className={'nav-item '+(view===key?'active':'')} onClick={()=>navigate(key)} aria-current={view===key?'page':undefined}><Icon size={19}/><span>{viewLabels[key]}</span>{key==='queue'&&scheduled>0&&<b>{scheduled}</b>}</button>)}</nav>
   <div className="nav-label second">SEU ESPAÇO</div><nav aria-label="Configuração">{[[Plug,'integrations'],[Settings,'settings']].map(([Icon,key])=><button key={key} className={'nav-item '+(view===key?'active':'')} onClick={()=>navigate(key)}><Icon size={19}/><span>{viewLabels[key]}</span></button>)}</nav>
   <div className="sidebar-bottom"><div className="local-dot"/><div>Salvo neste computador<small>Seus arquivos, no seu controle.</small></div></div>
   <button className="profile" onClick={()=>navigate('settings')}><span>V</span><div>Minha operação<small>Vitraya Studio · 1.0</small></div><Settings size={16}/></button>
  </aside>
  {menu&&<button className="menu-backdrop" onClick={()=>setMenu(false)} aria-label="Fechar navegação"/>}
  <div className="main-shell"><header className="topbar"><div className="breadcrumb"><button className="icon-button mobile-menu" onClick={()=>setMenu(!menu)} aria-label="Abrir navegação"><Menu size={22}/></button><span>Meu espaço</span><ChevronDown className="crumb-chevron" size={12}/><strong>{viewLabels[view]}</strong></div><div className="topbar-right"><span className="local-badge"><span/>Local</span><button className="avatar" onClick={()=>navigate('settings')} aria-label="Abrir preferências">V</button></div></header>
  <main id="main" tabIndex={-1}>
  {loadError&&<div className="notice error"><AlertCircle size={16}/>{loadError}<button onClick={refresh}>Reconectar</button></div>}
  {view==='catalog'&&<Catalog {...context}/>}
  {view==='shopee'&&<ShopeeOffers {...context} openCatalog={()=>navigate('catalog')}/>}
  {view==='studio'&&<Studio {...context} initialId={studioId}/>}
  {view==='queue'&&<Queue {...context}/>}
  {view==='channels'&&<Channels {...context}/>}
  {view==='templates'&&<Templates {...context}/>}
  {view==='coupons'&&<><Coupons coupons={state.coupons||[]} products={state.products} onSave={payload=>run(()=>api('/coupons'+(payload.id?'/'+payload.id:''),{method:payload.id?'PUT':'POST',body:payload}),'Cupom salvo.')} onDelete={id=>run(()=>api('/coupons/'+id,{method:'DELETE'}),'Cupom removido.')} notify={notify} busy={busy}/></>}
  {view==='integrations'&&<Integrations {...context}/>}
  {view==='settings'&&<Preferences {...context}/>}
  </main><footer className="app-footer">Feito para suas melhores descobertas.<span>Vitraya Studio · armazenamento local</span></footer></div>
  <nav className="mobile-tabs" aria-label="Acesso rápido">{[[LayoutGrid,'catalog'],[Palette,'studio'],[CalendarClock,'queue'],[Radio,'channels']].map(([Icon,key])=><button key={key} className={view===key?'active':''} onClick={()=>navigate(key)}><Icon size={21}/><span>{key==='queue'?'Fila':key==='studio'?'Estúdio':viewLabels[key]}</span></button>)}</nav>
  {modal?.type==='product'&&<ProductModal {...context} product={modal.product} onClose={()=>setModal(null)}/>}
  {modal?.type==='import'&&<ImportModal {...context} onClose={()=>setModal(null)}/>}
  {modal?.type==='bulk'&&<Modal title="Uma oferta de cada vez" description="Distribua os produtos selecionados ao longo do seu dia." onClose={()=>setModal(null)}><BulkScheduleForm {...context} onClose={()=>setModal(null)}/></Modal>}
  {modal?.type==='send'&&<Modal title="Publicar oferta" description="O envio só acontece após a sua confirmação." onClose={()=>setModal(null)}><SendForm {...context} product={modal.product} message={modal.message} onClose={()=>setModal(null)}/></Modal>}
  {modal?.type==='schedule'&&<ScheduleModal {...context} product={modal.product} message={modal.message} onClose={()=>setModal(null)}/>}
  {modal?.type==='confirm'&&<Modal title={modal.title} onClose={()=>setModal(null)}><p className="muted">{modal.body}</p><div className="dialog-actions"><button className="button" onClick={()=>setModal(null)}>Voltar</button><button className="button danger" disabled={busy} onClick={async()=>{try{await modal.action();setModal(null);}catch{}}}>{busy?'Aguarde…':modal.label||'Confirmar'}</button></div></Modal>}
  {toast&&<div className={'toast '+(toast.error?'toast-error':'')} role={toast.error?'alert':'status'}>{toast.error?<AlertCircle size={20}/>:<CheckCircle2 size={20}/>}<span>{toast.text}</span><button onClick={()=>setToast(null)} aria-label="Fechar aviso"><X size={16}/></button></div>}
 </div>;
}
function PageHeading({eyebrow,title,description,children}){return <div className="page-heading"><div>{eyebrow&&<p className="eyebrow">{eyebrow}</p>}<h1>{title}</h1>{description&&<p className="page-description">{description}</p>}</div><div className="heading-actions">{children}</div></div>;}
function Empty({icon:Icon=Package,title,description,children}){return <div className="empty"><div className="empty-icon"><Icon size={30}/></div><h2>{title}</h2><p>{description}</p><div className="empty-actions">{children}</div></div>;}
function Catalog(ctx){const {state,setModal,run,notify,selected,setSelected,studio}=ctx;const [query,setQuery]=useState(''),[market,setMarket]=useState('all'),[status,setStatus]=useState('all'),[sort,setSort]=useState('recent'),[exporting,setExporting]=useState(false);
 let products=state.products.filter(p=>(market==='all'||p.marketplace===market)&&(status==='all'||(status==='favorites'?p.tags.includes('favorito'):status==='noimage'?!p.image:p.status===status))&&`${p.title} ${p.category} ${p.tags.join(' ')}`.toLocaleLowerCase('pt-BR').includes(query.toLocaleLowerCase('pt-BR')));products=[...products].sort((a,b)=>sort==='price'?a.price-b.price:sort==='discount'?discount(b)-discount(a):new Date(b.updatedAt)-new Date(a.updatedAt));
 const ready=state.products.filter(p=>p.status==='ready').length;
 async function exportKit(){setExporting(true);try{const {default:JSZip}=await import('jszip');const zip=new JSZip();const chosen=state.products.filter(p=>selected.includes(p.id));for(const [i,p] of chosen.entries()){const dir=zip.folder(`${i+1}-${slug(p.title)}`);const canvas=document.createElement('canvas');await renderCreative(canvas,p,{brand:state.settings.brand,accent:state.settings.accent});const blob=await new Promise(r=>canvas.toBlob(r,'image/png'));dir.file('arte.png',blob);dir.file('mensagem.txt',messageFor(p,undefined,state.settings.signature));dir.file('produto.json',JSON.stringify(p,null,2));}download(await zip.generateAsync({type:'blob'}),'vitraya-kit-ofertas.zip');notify(`Kit com ${chosen.length} oferta(s) exportado.`);}catch(e){notify(e.message,true);}finally{setExporting(false);}}
 return <><PageHeading eyebrow="SUA CURADORIA, EM UM SÓ LUGAR" title="Boas ofertas começam aqui." description="Organize suas descobertas. A próxima publicação fica por sua conta."><button className="button" onClick={()=>setModal({type:'import'})}><Upload size={16}/>Importar catálogo</button><button className="button primary" onClick={()=>setModal({type:'product'})}><Plus size={18}/>Novo produto</button></PageHeading>
 <section className="curation-banner"><div className="banner-copy"><div className="banner-eyebrow"><span/>DA DESCOBERTA À PUBLICAÇÃO</div><h2>Seu próximo achadinho<br/>merece uma boa vitrine.</h2><p>Foto, preço e o seu link. Transforme o catálogo em ofertas prontas para compartilhar.</p><button onClick={()=>state.products.length?studio(state.products[0]):setModal({type:'product'})}>Criar minha próxima oferta <ArrowRight size={17}/></button></div><div className="paper-collage" aria-hidden="true"><div className="paper paper-back"><span>CURADORIA VITRAYA</span><ShoppingBag size={57} strokeWidth={1}/><b>um bom<br/>achado.</b></div><div className="paper paper-front"><span>ESCOLHIDO POR VOCÊ</span><div className="collage-spark">✳</div><strong>viu.<br/>gostou.<br/><em>compartilhou.</em></strong><div className="paper-price">SUA PRÓXIMA OFERTA <ArrowUpRight size={17}/></div></div><span className="collage-sticker">feito<br/>por você</span></div></section>
 <div className="catalog-summary"><div><span className="summary-icon"><Package size={17}/></span><strong>{state.products.length}</strong><span>produtos no catálogo</span></div><div><span className="summary-icon green"><CheckCircle2 size={17}/></span><strong>{ready}</strong><span>prontos para criar</span></div><div><span className="summary-icon orange"><Clock size={17}/></span><strong>{state.campaigns.filter(c=>['scheduled','ready','sending','failed','unknown'].includes(c.status)).length}</strong><span>na fila de publicação</span></div><span className="summary-note">Seus links de afiliado são preservados.</span></div>
 <div className="section-title"><h2>Meu catálogo <span>{products.length}</span></h2><details className="export-menu"><summary className="button small"><Download size={15}/>Exportar dados<ChevronDown size={13}/></summary><div>{['csv','xlsx','json'].map(f=><a key={f} href={'/api/export?format='+f}>Catálogo .{f}</a>)}</div></details></div>
 <div className="catalog-toolbar"><label className="search-field"><Search size={18}/><input aria-label="Buscar produto" value={query} onChange={e=>setQuery(e.target.value)} placeholder="Buscar por produto, categoria ou tag…"/>{query&&<button onClick={()=>setQuery('')} aria-label="Limpar busca"><X size={16}/></button>}</label><select aria-label="Filtrar marketplace" value={market} onChange={e=>setMarket(e.target.value)}><option value="all">Todos os marketplaces</option>{Object.entries(markets).map(([id,name])=><option key={id} value={id}>{name}</option>)}</select><select aria-label="Filtrar status" value={status} onChange={e=>setStatus(e.target.value)}><option value="all">Todos os status</option><option value="favorites">Favoritos</option><option value="noimage">Sem foto</option>{['draft','ready','archived'].map(s=><option key={s} value={s}>{statusLabel[s]}</option>)}</select><select aria-label="Ordenar catálogo" value={sort} onChange={e=>setSort(e.target.value)}><option value="recent">Mais recentes</option><option value="price">Menor preço</option><option value="discount">Maior desconto</option></select></div>
 {selected.length>0&&<div className="selection-bar"><label><input type="checkbox" checked={products.length>0&&products.every(p=>selected.includes(p.id))} onChange={e=>setSelected(e.target.checked?products.map(p=>p.id):[])}/>{selected.length} selecionado(s)</label><button className="button small" onClick={exportKit} disabled={exporting}>{exporting?'Preparando…':<><Download size={15}/>Baixar kit de ofertas</>}</button><button className="button small" onClick={()=>setModal({type:'bulk'})}><CalendarClock size={15}/>Organizar fila</button><button className="button small danger" onClick={()=>{const ids=[...selected];setModal({type:'confirm',title:`Excluir ${ids.length} produto(s)?`,body:'Eles saem do catálogo junto com as campanhas da fila. As fotos e a sua planilha original não são apagadas; você pode importar de novo depois.',label:`Excluir ${ids.length}`,action:async()=>{await run(()=>api('/products/delete',{method:'POST',body:{ids}}),`${ids.length} produto(s) removido(s).`);setSelected([]);}});}}><Trash2 size={15}/>Excluir selecionados</button><button className="text-button" onClick={()=>setSelected([])}>Limpar seleção</button></div>}
 {!state.products.length?<Empty title="O catálogo é seu. Comece com um achado." description="Importe sua planilha e suas fotos ou cadastre o primeiro produto com seu link de afiliado."><button className="button primary" onClick={()=>setModal({type:'import'})}><Upload size={16}/>Importar meus produtos</button><button className="button" onClick={()=>run(()=>api('/demo',{method:'POST'}),'Demonstração carregada. Todos os produtos são fictícios.').catch(()=>{})}>Explorar com exemplos fictícios</button><a className="text-button" href="/exemplos/catalogo.csv" download>Baixar planilha modelo</a></Empty>:!products.length?<Empty icon={Search} title="Nenhum produto com esses filtros" description="Tente outra palavra ou selecione todos os marketplaces."><button className="button" onClick={()=>{setQuery('');setMarket('all');setStatus('all');}}>Limpar filtros</button></Empty>:<div className="product-grid">{products.map(p=><article className={'product-card '+(selected.includes(p.id)?'is-selected':'')} key={p.id}><div className="product-photo"><label className="product-select"><input type="checkbox" aria-label={'Selecionar '+p.title} checked={selected.includes(p.id)} onChange={e=>setSelected(e.target.checked?[...selected,p.id]:selected.filter(id=>id!==p.id))}/></label>{discount(p)>0&&<span className="discount-tag">−{discount(p)}%</span>}{p.image?<img src={p.image} alt={p.title} loading="lazy"/>:<div className="no-image"><ImageIcon size={38} strokeWidth={1}/><span>Sem foto</span></div>}<button className={'favorite-button '+(p.tags.includes('favorito')?'is-favorite':'')} aria-label={(p.tags.includes('favorito')?'Desfavoritar ':'Favoritar ')+p.title} aria-pressed={p.tags.includes('favorito')} onClick={()=>run(()=>api('/products/'+p.id,{method:'PUT',body:{tags:p.tags.includes('favorito')?p.tags.filter(t=>t!=='favorito'):[...p.tags,'favorito']}})).catch(()=>{})}><Bookmark size={16}/></button><button className="photo-edit" onClick={()=>setModal({type:'product',product:p})} aria-label={'Editar '+p.title}><Edit3 size={16}/></button></div><div className="product-info"><div className="product-meta"><Market id={p.marketplace}/><span className={'status-dot '+p.status} title={statusLabel[p.status]}>{statusLabel[p.status]}</span></div><h3>{p.title}</h3><p className="category">{p.category||'Sem categoria'}</p><div className="price-row"><strong>{money(p.price)}</strong>{p.originalPrice>p.price&&<del>{money(p.originalPrice)}</del>}</div>{p.coupon&&<div className="coupon-tag">CUPOM <b>{p.coupon}</b></div>}<div className="product-bottom"><button onClick={()=>studio(p)}>Criar oferta <ArrowUpRight size={17}/></button><button className="icon-button" title="Copiar link de afiliado" aria-label={'Copiar link de '+p.title} onClick={()=>navigator.clipboard.writeText(p.affiliateUrl).then(()=>notify('Link copiado.')).catch(()=>notify('Permita acesso à área de transferência.',true))}><Copy size={16}/></button></div></div></article>)}</div>}
 {state.products.some(p=>p.tags.some(t=>['demonstracao','demonstração'].includes(t)))&&<p className="demo-note"><AlertCircle size={14}/>Os produtos com tag “demonstracao” são exemplos fictícios. Substitua fotos, preços e links antes de publicar.</p>}
 </>;
}
function Modal({title,description,children,onClose,wide=false}){const ref=useRef(null);const titleId=useId(),descriptionId=useId();useEffect(()=>{const previous=document.activeElement;ref.current?.showModal();return()=>previous?.focus();},[]);return <dialog ref={ref} aria-labelledby={titleId} aria-describedby={description?descriptionId:undefined} className={'dialog '+(wide?'wide':'')} onCancel={e=>{e.preventDefault();onClose();}} onClick={e=>{if(e.target===ref.current)onClose();}}><div className="dialog-header"><div><h2 id={titleId}>{title}</h2>{description&&<p id={descriptionId}>{description}</p>}</div><button className="icon-button" onClick={onClose} aria-label="Fechar janela"><X size={20}/></button></div>{children}</dialog>;}
function Field({label,children,hint}){return <label className="field"><span>{label}</span>{children}{hint&&<small>{hint}</small>}</label>;}
function ProductModal({product,run,notify,onClose,setModal}){const [form,setForm]=useState(product||{...blankProduct}),[price,setPrice]=useState(product?(product.price/100).toFixed(2).replace('.',','):''),[original,setOriginal]=useState(product?.originalPrice?(product.originalPrice/100).toFixed(2).replace('.',','):''),[tags,setTags]=useState(product?.tags.join(', ')||''),[saving,setSaving]=useState(false),[error,setError]=useState('');const update=(key,value)=>setForm(p=>({...p,[key]:value}));
 async function upload(file){if(!file)return;setSaving(true);try{const fd=new FormData();fd.append('file',file);const result=await api('/media',{method:'POST',body:fd});update('image',result.url);}catch(e){setError(e.message);}finally{setSaving(false);}}
 async function save(e){e.preventDefault();setError('');setSaving(true);try{const amount=cents(price),old=original?cents(original):0;if(!Number.isFinite(amount)||amount<=0)throw new Error('Informe um preço maior que zero.');if(original&&(!Number.isFinite(old)||old<amount))throw new Error('O preço original deve ser igual ou maior que o atual.');await run(()=>api('/products'+(product?'/'+product.id:''),{method:product?'PUT':'POST',body:{...form,price:amount,originalPrice:old,tags:tags.split(',').map(x=>x.trim()).filter(Boolean)}}),'Produto salvo no catálogo.');onClose();}catch(e){setError(e.message);}finally{setSaving(false);}}
 return <Modal title={product?'Editar produto':'Um novo achado'} description="Cadastre o produto com o seu link original de afiliado." onClose={onClose} wide><form onSubmit={save}><div className="product-form"><div className="photo-upload">{form.image?<img src={form.image} alt="Foto do produto"/>:<><ImagePlus size={36}/><p>Uma boa foto faz diferença.</p></>}<label className="button small"><Upload size={15}/>{form.image?'Trocar foto':'Escolher foto'}<input type="file" accept="image/png,image/jpeg,image/webp" className="sr-only" onChange={e=>upload(e.target.files[0])}/></label>{form.image&&<button type="button" className="text-button" onClick={()=>update('image','')}>Remover foto</button>}<small>JPG, PNG ou WebP · até 10 MB</small></div><div className="form-fields"><Field label="Nome do produto"><input required maxLength={200} value={form.title} onChange={e=>update('title',e.target.value)} placeholder="Ex.: Bolsa tiracolo com alça ajustável" autoFocus/></Field><div className="form-row"><Field label="Marketplace"><select value={form.marketplace} onChange={e=>update('marketplace',e.target.value)}>{Object.entries(markets).map(([k,v])=><option key={k} value={k}>{v}</option>)}</select></Field><Field label="Categoria"><input value={form.category} onChange={e=>update('category',e.target.value)} maxLength={80} placeholder="Moda, casa, beleza…"/></Field></div><div className="form-row"><Field label="Preço atual (R$)"><input required inputMode="decimal" value={price} onChange={e=>setPrice(e.target.value)} placeholder="89,90"/></Field><Field label="Preço original (R$)"><input inputMode="decimal" value={original} onChange={e=>setOriginal(e.target.value)} placeholder="Opcional"/></Field></div><Field label="Link de afiliado" hint="Cole exatamente o link gerado pela sua conta. Ele será preservado."><input required type="url" value={form.affiliateUrl} onChange={e=>update('affiliateUrl',e.target.value)} placeholder="https://…"/></Field><div className="form-row"><Field label="Cupom"><input value={form.coupon} onChange={e=>update('coupon',e.target.value)} maxLength={60} placeholder="Opcional"/></Field><Field label="Status"><select value={form.status} onChange={e=>update('status',e.target.value)}>{['draft','ready','archived'].map(s=><option value={s} key={s}>{statusLabel[s]}</option>)}</select></Field></div><Field label="Tags"><input value={tags} onChange={e=>setTags(e.target.value)} placeholder="Separe por vírgula: verão, favoritos"/></Field><Field label="Observações"><textarea rows={2} value={form.description} onChange={e=>update('description',e.target.value)} maxLength={2000} placeholder="Informações para a sua curadoria"/></Field></div></div>{error&&<div className="notice error" role="alert">{error}</div>}<div className="dialog-actions">{product&&<button type="button" className="button danger ghost push-left" onClick={()=>setModal({type:'confirm',title:'Excluir este produto?',body:'Ele sairá do catálogo. As campanhas relacionadas também poderão ser removidas.',label:'Excluir produto',action:()=>run(()=>api('/products/'+product.id,{method:'DELETE'}),'Produto excluído.')} )}><Trash2 size={16}/>Excluir</button>}<button type="button" className="button" onClick={onClose}>Cancelar</button><button className="button primary" disabled={saving}>{saving?'Salvando…':'Salvar produto'}</button></div></form></Modal>;
}
