 async function read(file){if(!file)return;setWorking(true);setError('');setResult(null);setPreview(null);setFilename('');try{const fd=new FormData();fd.append('file',file);const p=await api('/import/preview',{method:'POST',body:fd});setPreview(p);setFilename(file.name);}catch(e){setError(e.message);}finally{setWorking(false);}}
