function Templates({state,run,setModal,busy}){const [id,setId]=useState(''),[name,setName]=useState(''),[body,setBody]=useState(defaultBody),[error,setError]=useState('');const vars=['titulo','preco','preco_original','desconto','cupom','link','loja','assinatura'];async function save(e){e.preventDefault();try{await run(()=>api('/templates'+(id?'/'+id:''),{method:id?'PUT':'POST',body:{name,body}}),'Modelo de mensagem salvo.');setId('');setName('');setBody(defaultBody);setError('');}catch(e){setError(e.message);}}return <><PageHeading eyebrow="A VOZ DA SUA CURADORIA" title="Mensagens com a sua cara." description="Salve modelos e deixe o produto preencher preço, cupom e link."/><div className="two-column"><section className="panel"><h2>{id?'Editar modelo':'Novo modelo'}</h2><form onSubmit={save}><Field label="Nome do modelo"><input required value={name} maxLength={100} onChange={e=>setName(e.target.value)} placeholder="Ex.: Oferta do dia"/></Field><Field label="Mensagem"><textarea required rows={13} maxLength={5000} value={body} onChange={e=>setBody(e.target.value)}/></Field><div className="variable-list">{vars.map(v=><button type="button" key={v} onClick={()=>setBody(body+'{'+v+'}')}>{'{'+v+'}'}</button>)}</div><p className="muted small-text">Mantenha {'{link}'} e identifique a publicidade na mensagem.</p>{error&&<p className="text-error" role="alert">{error}</p>}<div className="inline-actions"><button className="button primary" disabled={busy}><Bookmark size={16}/>{busy?'Salvando…':'Salvar modelo'}</button>{id&&<button type="button" className="button" onClick={()=>{setId('');setName('');setBody(defaultBody);}}>Cancelar edição</button>}</div></form></section><section>{!state.templates.length?<Empty icon={FileText} title="O primeiro modelo já está no editor" description="Adapte a mensagem ao seu público e salve para usar no Estúdio."/>:state.templates.map(t=><article key={t.id} className="template-card"><div><h3>{t.name}</h3><button className="icon-button" aria-label={'Excluir modelo '+t.name} onClick={()=>setModal({type:'confirm',title:'Excluir modelo?',body:'As mensagens já guardadas na fila permanecem iguais.',label:'Excluir modelo',action:()=>run(()=>api('/templates/'+t.id,{method:'DELETE'}),'Modelo excluído.')} )}><Trash2 size={16}/></button></div><pre>{t.body}</pre><button className="button small" onClick={()=>{setId(t.id);setName(t.name);setBody(t.body);}}><Edit3 size={15}/>Editar modelo</button></article>)}</section></div></>;}
function Integrations({state,...context}){return <><PageHeading eyebrow="CADA PLATAFORMA, COM CLAREZA" title="Mais caminhos para seus achados." description="Configure os destinos e acompanhe o acesso a cada plataforma."/><Connections {...context} state={state}/><div className="notice"><Plug size={18}/><span>O catálogo local funciona com todos os marketplaces abaixo. Na Shopee, a busca de ofertas e os links de afiliado usam a Open API oficial (em Ofertas Shopee). Nas demais plataformas, a sincronização e a geração automática de links ainda não estão conectadas.</span></div><div className="integration-grid">{(state.integrations||[]).map(i=><article className="integration-card" key={i.id}><div className="integration-top"><Market id={i.id}/><span className="status-pill manual">Importação disponível</span></div><h2>{i.name}</h2><p>{i.description}</p><div className="integration-capability"><Check size={15}/>Seu link original no catálogo</div><div className="integration-capability"><Check size={15}/>Artes, legendas e exportação</div>{i.id==='shopee'?<div className={'integration-capability '+(state.shopee?.status==='connected'?'':'muted')}>{state.shopee?.status==='connected'?<Check size={15}/>:<Clock size={15}/>}{state.shopee?.status==='connected'?'Open API conectada: busca e links':state.shopee?.configured?'Open API configurada: teste em Ofertas Shopee':'Open API: configure em Ofertas Shopee'}</div>:<div className="integration-capability muted"><Clock size={15}/>API: acesso e validação pendentes</div>}{i.url&&<a className="text-button" href={i.url} target="_blank" rel="noreferrer">Acessar plataforma oficial <ExternalLink size={14}/></a>}</article>)}</div><section className="panel integration-whatsapp"><Radio size={30}/><div><h2>WhatsApp e canais de divulgação</h2><p>Prepare o kit com foto e legenda, abra o canal e confirme a publicação. Cadastrar um canal aqui não conecta sua conta nem autoriza disparos. O Studio não lê conversas ou contatos.</p></div></section></>;}
function Preferences({state,run,notify,setModal,busy}){const [form,setForm]=useState(state.settings),[error,setError]=useState(''),[restoring,setRestoring]=useState(false);async function save(e){e.preventDefault();try{await run(()=>api('/settings',{method:'PUT',body:form}),'Preferências salvas.');setError('');}catch(e){setError(e.message);}}async function restore(file){if(!file)return;setRestoring(true);try{const fd=new FormData();fd.append('file',file);const r=await run(()=>api('/restore',{method:'POST',body:fd}));notify(`Backup importado: ${r.imported??r.products??0} produto(s). Dados existentes preservados.`);}catch(e){setError(e.message);}finally{setRestoring(false);}}return <><PageHeading eyebrow="A SUA MARCA NA OFERTA" title="Um espaço do seu jeito." description="Ajuste a assinatura dos criativos e cuide dos seus arquivos."/><div className="two-column"><section className="panel"><h2>Identidade da curadoria</h2><form onSubmit={save}><Field label="Nome nas artes"><input required maxLength={40} value={form.brand||''} onChange={e=>setForm({...form,brand:e.target.value})}/></Field><Field label="Cor da marca"><div className="color-input"><input type="color" value={form.accent||'#5143c7'} onChange={e=>setForm({...form,accent:e.target.value})}/><span>{form.accent}</span></div></Field><Field label="Assinatura da mensagem" hint="Ex.: Mais achados no canal da Vitraya"><input maxLength={200} value={form.signature||''} onChange={e=>setForm({...form,signature:e.target.value})}/></Field>{error&&<p className="text-error" role="alert">{error}</p>}<button className="button primary" disabled={busy}>{busy?'Salvando…':'Salvar preferências'}</button></form></section><section className="panel"><h2>Seu catálogo, protegido</h2><p className="muted">O banco e as fotos ficam na pasta local de dados exibida no terminal. Crie backups para levar seu trabalho a outro computador.</p><a className="button" href="/api/backup"><Archive size={17}/>Baixar backup com fotos</a><div className="studio-divider"/><h3>Trazer um backup</h3><p className="muted">Restauração aditiva: produtos repetidos são ignorados e os dados existentes são preservados.</p><label className="button"><Upload size={17}/>{restoring?'Restaurando…':'Selecionar backup .zip'}<input className="sr-only" disabled={restoring} type="file" accept=".zip" onChange={e=>restore(e.target.files[0])}/></label><div className="studio-divider"/><h3>Planilhas e arquivos</h3><div className="inline-actions">{['csv','xlsx','json'].map(f=><a key={f} className="button small" href={'/api/export?format='+f}><Download size={14}/>{f.toUpperCase()}</a>)}</div></section></div><section className="panel local-info"><Monitor size={22}/><p><strong>Este é um aplicativo local, de uso pessoal.</strong><br/>Acesso restrito a este computador. Para usar em equipe ou pela internet, será necessária uma implantação com autenticação e isolamento próprios.</p></section></>;}

createRoot(document.getElementById('root')).render(<App/>);
